def is_perfectly_balanced(s):
    n = len(s)
    # Check all possible substrings
    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            freq = {}
            for c in substring:
                freq[c] = freq.get(c, 0) + 1

            # Get all unique characters in the substring
            chars = list(freq.keys())
            # Check if any two characters have frequency difference > 1
            max_freq = max(freq.values())
            min_freq = min(freq.values())
            if max_freq - min_freq > 1:
                return False
    return True

